import {example,validate,initial,labels,tiles} from './workshop-engine.mjs';
import {drawRoom,drawCurve} from './draw.mjs';
const $=id=>document.getElementById(id),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let config=example(),tool='wall',worker=null,run=null,index=0,playing=false,editing=true,last=0,elapsed=0,generation=0;
const names={robot:'机器人',item:'物件',...tiles},countNodes={};
for(const [k,name] of Object.entries(names)){const b=document.createElement('button');b.textContent=name==='空地'?'橡皮擦':name;b.dataset.tool=k;b.setAttribute('aria-pressed',String(k===tool));b.onclick=()=>{tool=k;document.querySelectorAll('[data-tool]').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.tool===k)));if(!editing){editing=true;playing=false;render();}$('hint').textContent=`已选择${b.textContent}，点击格子摆放。`;};$('tools').append(b);}
for(let i=0;i<35;i++){const b=document.createElement('button');b.onclick=()=>paint(i);$('grid').append(b);}
for(const [k,name] of Object.entries(labels)){const l=document.createElement('label');l.className='reward-field';l.textContent=name;const input=document.createElement('input');input.type='number';input.min=-20;input.max=20;input.step=.1;input.value=config.rewards[k];input.id=`reward-${k}`;input.oninput=()=>{invalidate();if(input.value!==''&&input.checkValidity())config.rewards[k]=Number(input.value);};l.append(input);$('rewards').append(l);const box=document.createElement('div');box.textContent=name;const n=document.createElement('strong');n.textContent='0';box.append(n);countNodes[k]=n;$('counts').append(box);}
function cancel(){generation++;worker?.terminate();worker=null;$('cancel').hidden=true;$('train').disabled=false;}
function invalidate(){cancel();run=null;index=0;playing=false;editing=true;elapsed=0;$('progress').value=0;$('episodes').textContent='0 局';drawCurve($('curve'),[]);$('status').textContent='场景已修改，点击训练学习新的规则。';$('verdict').textContent='还没有这份规则下的动作记录。训练后，观察它实际做了什么。';render();}
function paint(i){const c=structuredClone(config);if(tool==='robot'||tool==='item'){if(c.cells[i]!=='empty'){$('hint').textContent='请先用橡皮擦清空这个格子，再放机器人或物件。';return;}c[tool==='robot'?'start':'item']=i;}else{if((i===c.start||i===c.item)&&tool!=='empty'){$('hint').textContent='先把机器人或物件挪开，再在这里摆放元素。';return;}c.cells[i]=tool;}try{config=validate(c);invalidate();$('hint').textContent=`已在第 ${Math.floor(i/7)+1} 行、第 ${i%7+1} 列放置${names[tool]}。`;}catch(e){$('hint').textContent=e.message;}}
function render(blend=1){const f=run?.frames[index]||{state:initial(config),total:0,event:'等待训练'},prev=run?.frames[Math.max(0,index-1)];drawRoom($('room'),'workshop',editing?{state:initial(config)}:f,editing?null:prev,blend,editing?[]:run?.frames.slice(0,index+1)||[],config);$('grid').hidden=!editing;$('badge').textContent=editing?'布置房间':playing?'策略回放':'观察模式';$('play').disabled=!run;$('replay').disabled=!run;$('play').textContent=playing?'暂停 Ⅱ':'播放 ▶';$('steps').textContent=`${index} / 80 步`;$('score').textContent=f.total.toFixed(1);$('event').textContent=f.event;$('item-state').textContent=({[-1]:'机器人手中',[-2]:'垃圾桶里',[-3]:'地毯下面',[-4]:'收件点'})[f.state.item]||'房间里';const counts=Object.fromEntries(Object.keys(labels).map(k=>[k,0]));if(run)for(let j=1;j<=index;j++){counts.step++;run.frames[j].events.forEach(k=>{if(k in counts)counts[k]++;});}for(const k in counts)countNodes[k].textContent=counts[k];[...$('grid').children].forEach((b,i)=>b.setAttribute('aria-label',`第 ${Math.floor(i/7)+1} 行，第 ${i%7+1} 列：${tiles[config.cells[i]]}${config.start===i?'，机器人':''}${config.item===i?'，物件':''}`));}
function readConfig(){for(const k of Object.keys(labels)){const n=$(`reward-${k}`);if(n.value===''||!n.reportValidity())throw Error('请检查分数：需要 −20 到 20 的数字。');config.rewards[k]=Number(n.value);}if($('seed').value===''||!$('seed').reportValidity())throw Error('请填写有效的训练种子。');config.seed=Number($('seed').value);return validate(config);}
function start(){let snapshot;try{snapshot=readConfig();}catch(e){$('status').textContent=e.message;return;}invalidate();editing=false;$('train').disabled=true;$('cancel').hidden=false;$('status').textContent='正在本机试错训练…';const token=generation;worker=new Worker(new URL('./workshop-worker.mjs',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(token!==generation)return;if(data.type==='progress'){$('progress').value=data.episode;$('episodes').textContent=`${data.episode.toLocaleString()} 局`;drawCurve($('curve'),data.curve);}else if(data.type==='done'){run=data.run;cancel();playing=!reduced;index=0;elapsed=0;$('status').textContent=`训练完成 · 学过 ${run.states.toLocaleString()} 个状态 · 种子 ${snapshot.seed}`;$('verdict').textContent='自由观察 80 步。可以暂停、重播，或修改地图与分数重新训练。';render();}else{cancel();$('status').textContent=data.message;}};worker.onerror=()=>{cancel();$('status').textContent='训练未完成，请重试或简化地图。';};worker.postMessage(snapshot);render();}
function hydrate(){for(const k in labels)$(`reward-${k}`).value=config.rewards[k];$('seed').value=config.seed;invalidate();}
$('seed').oninput=()=>invalidate();$('train').onclick=start;$('cancel').onclick=()=>{cancel();$('status').textContent='已取消。场景保留，可随时重新训练。';};$('play').onclick=()=>{if(!run)return;editing=false;if(index===80){index=0;elapsed=0;}playing=!playing;render();};$('replay').onclick=()=>{index=0;elapsed=0;editing=false;playing=true;render();};$('edit').onclick=()=>{playing=false;editing=true;render();$('hint').textContent='编辑中：点击格子修改布局。修改后需要重新训练。';};
$('save').onclick=()=>{try{const c=readConfig(),u=URL.createObjectURL(new Blob([JSON.stringify(c,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='reward-lab-workshop.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);$('file-status').textContent='已发起场景下载。文件包含地图、分数和种子。';}catch(e){$('file-status').textContent=e.message;}};
$('load').onclick=()=>$('file').click();$('file').onchange=async()=>{const f=$('file').files[0];if(!f)return;try{if(f.size>65536)throw Error('场景文件不能超过 64 KB。');const c=validate(JSON.parse(await f.text()));config=c;hydrate();$('file-status').textContent='场景已载入。点击训练，观察这份规则。';}catch(e){$('file-status').textContent=`未载入：${e.message}`;}finally{$('file').value='';}};
$('reset').onclick=()=>{config=example();hydrate();$('file-status').textContent='已恢复示例场景。';};
function tick(now){const dt=Math.min(100,now-last);last=now;if(playing&&run){elapsed+=dt;const duration=650/Number($('speed').value);if(elapsed>=duration){elapsed-=duration;index++;if(index>=80){index=80;playing=false;$('verdict').textContent=`观察结束，累计 ${run.frames[80].total.toFixed(1)} 分。下方是完整行动计数；这里没有通关标准。`;}}render(playing?Math.min(1,elapsed/(duration*.7)):1);}requestAnimationFrame(tick);}render();requestAnimationFrame(tick);
